  const qa=sel=>panes().flatMap(pane=>[...pane.querySelectorAll(sel)]);
  const owns=node=>Boolean(node)&&panes().some(pane=>pane.contains(node));
  function saved(){try{return JSON.parse(localStorage.getItem(PREF_KEY))||{};}catch{return {};}}
