    const parents=entries.map((_,i)=>i),find=i=>parents[i]===i?i:(parents[i]=find(parents[i])),join=(a,b)=>{parents[find(b)]=find(a);},strong=new Map(),names=new Map();
    entries.forEach((entry,i)=>{for(const key of entry.strong){if(strong.has(key))join(i,strong.get(key));else strong.set(key,i);}if(entry.fallback){if(!names.has(entry.fallback))names.set(entry.fallback,[]);names.get(entry.fallback).push(i);}});
    // A name match can bridge providers only when their known IDs do not conflict.
