      const id=strongIds.find(id=>id.startsWith('sleeper:'))||strongIds[0]||'entry:'+base.league.id+':'+base.side+':'+base.category+':'+base.index;
      for(const side of ['own','opponent']){const exposure=impacts.filter(e=>e.side===side);if(!exposure.length)continue;const p=exposure[0].player,linked=[...new Set(exposure.map(e=>e.player.gameId).filter(Boolean).map(String))];result[side].push({...p,id,position:position(p),points:null,slot:null,espnId:impacts.find(e=>identityValue(e.player.espnId))?.player.espnId||null,photo:impacts.find(e=>safeURL(e.player.photo))?.player.photo||p.photo,gameId:linked.length===1?linked[0]:null,impacts,exposure});}
