  function primaryFantasySource(record){const sources=fantasySources(record);return sources.find(x=>x.status==='snapshot')||sources.find(x=>/matchup|fantasy/i.test(x.provider||''))||sources[0];}
  function cardFreshness(record){const source=primaryFantasySource(record);if(!source)return record.data?'<p>Fantasy source check time unavailable.</p>':'';const label={live:'Matchup checked',cached:'Cached matchup',snapshot:'Saved fantasy snapshot',stale:'Stale matchup',unavailable:'Matchup source unavailable'}[source.status]||'Source status unavailable';return `<p class="gd-card-freshness gd-source-${esc(source.status)}"><b>${esc(label)}</b><span>${esc(stamp(source.fetchedAt))}</span>${link(source.url,'Source')}</p>${source.status==='snapshot'?'<p>Fantasy snapshot; NFL games update separately.</p>':''}`;}
