    const impacts=visibleImpacts(p),key=side+':'+p.id,g=playerGame(p),opposite=p.impacts.filter(e=>e.side!==side),label=`${p.name}, ${p.position}, ${p.team||'team unknown'}, ${impacts.length} league ${impacts.length===1?'entry':'entries'}. ${impacts.map(e=>e.league.name+': '+(finite(e.player.points)?points(e.player.points)+' reported points':'points unavailable')).join('; ')}. ${g?status(g):'No linked game on this slate'}. Open all league impacts.`;
