    const ahead=outlook.filter(o=>o.gap!==null&&o.gap>0),behind=outlook.filter(o=>o.gap!==null&&o.gap<0),unknownGap=outlook.filter(o=>o.gap===null);
    const conflict=shared.find(p=>playerGame(p)?.state!=='post'),helpsSeveral=mutual[0];
