    const form=variables.map((v,i)=>`<div class="gd-scenario-variable"><label for="gd-scenario-player-${i}">Player ${i+1}<select id="gd-scenario-player-${i}" data-key="scenario-player-${i}" data-scenario="player" data-index="${i}">${candidates.map(p=>`<option value="${esc(p.id)}" ${v.player?.id===p.id?'selected':''}>${esc(p.name)} · ${esc(p.team)}</option>`).join('')}</select></label><label for="gd-scenario-event-${i}">Additional production<select id="gd-scenario-event-${i}" data-key="scenario-event-${i}" data-scenario="event" data-index="${i}">${I.eventKeys(v.player).map(k=>`<option value="${k}" ${k===v.event?'selected':''}>${esc(I.events[k].label)}</option>`).join('')}</select></label><label class="gd-scenario-count" for="gd-scenario-count-${i}">How many?<input id="gd-scenario-count-${i}" data-key="scenario-count-${i}" data-scenario="count" data-index="${i}" type="number" min="0" max="100" step="1" value="${v.count}"></label></div>`).join('');
