  async function loadNews(force=false){
    newsRequest?.abort();
    const token=++newsSeq,controller=new AbortController();newsRequest=controller;
    try{
      const data=await fetchJSON('/api/fantasycast/news'+(force?'?refresh=1':''),controller.signal);
      if(!host||token!==newsSeq)return;
      s.news={articles:list(data?.articles),sources:list(data?.sources),error:''};s.newsLoaded=true;
    }catch(e){
      if(!host||token!==newsSeq||e.name==='AbortError')return;
      // Keep whatever was already published rather than emptying the list on one failure.
      s.news={articles:list(s.news?.articles),sources:list(s.news?.sources),error:e.message};s.newsLoaded=true;
    }
    region('gd-news',newsSection());
    scheduleNews();
  }
