  // Update existing nodes so polling preserves keyboard focus, open disclosures and scroll.
  function morph(current,next){
    if(current.nodeType!==next.nodeType||current.nodeName!==next.nodeName){current.replaceWith(next.cloneNode(true));return;}
    if(current.nodeType===Node.TEXT_NODE){if(current.textContent!==next.textContent)current.textContent=next.textContent;return;}
    if(current.nodeType!==Node.ELEMENT_NODE)return;
    for(const a of [...current.attributes])if(!next.hasAttribute(a.name)&&!(current.tagName==='DETAILS'&&a.name==='open'))current.removeAttribute(a.name);
    for(const a of next.attributes)if(current.getAttribute(a.name)!==a.value)current.setAttribute(a.name,a.value);
    const keyed=new Map([...current.children].filter(x=>x.dataset.key).map(x=>[x.dataset.key,x]));
    [...next.childNodes].forEach((n,i)=>{let old=current.childNodes[i];const key=n.nodeType===1?n.dataset.key:null;if(key&&keyed.has(key)&&keyed.get(key)!==old){current.insertBefore(keyed.get(key),old||null);old=current.childNodes[i];}if(!old)current.append(n.cloneNode(true));else morph(old,n);});
    while(current.childNodes.length>next.childNodes.length)current.lastChild.remove();
    if(current.tagName==='INPUT'&&next.hasAttribute('value')&&document.activeElement!==current)current.value=next.getAttribute('value');
    if(current.tagName==='SELECT'&&document.activeElement!==current){const selected=next.querySelector('option[selected]');if(selected)current.value=selected.value;}
  }
