  function syncControls(){const root=q('.gameday');if(!root)return;for(const node of qa('.gameday,.gd-rail')){node.dataset.focus=s.focus;node.dataset.density=s.density;node.dataset.combined=String(combined());}const picker=q('#gd-league');if(picker)picker.value=s.league;q('#gd-lineup-title').textContent=combined()?'Your players across leagues':'The fantasy matchup';q('[data-key="view-matchup"]').textContent=combined()?'My matchups':'My matchup';q('.gd-panel-foot').textContent=combined()?'Select a player to see every selected league’s impact and their NFL game.':'Select a player to follow their NFL game and see this league’s scoring context.';qa('[data-action]').forEach(b=>{const a=b.dataset.action;if(['focus','filter','roster'].includes(a))b.setAttribute('aria-pressed',String(s[a]===b.dataset.value));if(a==='detail')b.setAttribute('aria-pressed',String(s.detailTab===b.dataset.value));if(a==='auto'){b.setAttribute('aria-pressed',String(s.auto));b.textContent=s.auto?'Auto refresh on':'Auto refresh off';}});}
