      const delta=I.changes(previous,records(),universe());s.changes=[...delta,...s.changes].slice(0,12);
      window.NFLWinChance?.observeMatchups(combined()?s.overview:[{league:selectedLeague(),data:s.dashboard}]);
      publishScoreChecks();
      if(!weekGames().some(g=>String(g.id)===s.gameId)){const candidate=games().find(g=>g.state==='in'&&connected(g,'own').length)||games().find(g=>connected(g,'own').length)||games().find(g=>g.state==='in')||games()[0];s.gameId=candidate?String(candidate.id):'';s.detail=null;}
